screenPanels.initJs:
function(container, apiUrl, tables) {
  const errorLogTable = tables.find(t => t.tableName === 'エラーログ') || tables[0];
  const errorLogRecords = errorLogTable.records || [];

  let allErrors = [...errorLogRecords];
  let selectedErrorId = null;

  // ========== 1. KPI 計算 ==========
  function updateKPIs() {
    const pending = allErrors.filter(e => e.ステータス === '未対応').length;
    const critical = allErrors.filter(e => e.重要度 === 'CRITICAL').length;
    const warning = allErrors.filter(e => e.重要度 === 'WARNING').length;
    const resolved = allErrors.filter(e => e.ステータス === '解決済み').length;

    container.querySelector('[data-testid="kpi-pending-errors"]').textContent = pending;
    container.querySelector('[data-testid="kpi-critical-errors"]').textContent = critical;
    container.querySelector('[data-testid="kpi-warning-errors"]').textContent = warning;
    container.querySelector('[data-testid="kpi-resolved-errors"]').textContent = resolved;
  }

  // ========== 2. テーブル再描画 ==========
  function renderErrors(errors) {
    const tbody = container.querySelector('#error-tbody');
    if (errors.length === 0) {
      tbody.innerHTML = '<tr style="height:2rem; text-align:center; color:var(--text-muted);"><td colspan="7">該当するエラーがありません</td></tr>';
      return;
    }

    tbody.innerHTML = errors.map(e => {
      const severityColor = e.重要度 === 'CRITICAL' ? '#e74c3c' : e.重要度 === 'WARNING' ? '#f39c12' : '#27ae60';
      const statusBg = e.ステータス === '未対応' ? 'rgba(231,76,60,0.15)' : e.ステータス === '対応中' ? 'rgba(243,156,18,0.15)' : 'rgba(39,174,96,0.15)';

      return `<tr data-id="${e.エラーログID}" style="border-bottom:1px solid rgba(255,255,255,0.05); cursor:pointer; transition:background 0.2s;" onmouseover="this.style.background='rgba(255,255,255,0.03)'" onmouseout="this.style.background='transparent'">
        <td style="padding:0.5rem; color:var(--text-muted); font-size:0.75rem; font-family:monospace; word-break:break-all;">${(e.受注データID || '—').substring(0, 8)}</td>
        <td style="padding:0.5rem; color:var(--text); font-weight:500;">${e.受注番号 || '—'}</td>
        <td style="padding:0.5rem; color:var(--text); font-family:monospace;">${e.エラーコード || '—'}</td>
        <td style="padding:0.5rem; color:var(--text); font-size:0.8rem; max-width:120px; overflow:hidden; text-overflow:ellipsis; white-space:nowrap;">${e.エラーメッセージ || '—'}</td>
        <td style="padding:0.5rem; text-align:center;"><span style="background:${severityColor}20; color:${severityColor}; padding:0.25rem 0.5rem; border-radius:0.25rem; font-size:0.75rem; font-weight:600;">${e.重要度 || '—'}</span></td>
        <td style="padding:0.5rem; text-align:center;"><span style="background:${statusBg}; color:var(--text); padding:0.25rem 0.5rem; border-radius:0.25rem; font-size:0.75rem;">${e.ステータス || '—'}</span></td>
        <td style="padding:0.5rem; text-align:center; color:var(--text-muted); font-size:0.75rem;">${e.作成日時 ? new Date(e.作成日時).toLocaleString('ja-JP', {month:'2-digit', day:'2-digit', hour:'2-digit', minute:'2-digit'}) : '—'}</td>
      </tr>`;
    }).join('');
  }

  // ========== 3. 詳細パネル表示 ==========
  function showDetail(errorId) {
    const error = allErrors.find(e => e.エラーログID === errorId);
    if (!error) return;

    selectedErrorId = errorId;
    container.querySelector('#detail-order-id').textContent = error.受注データID || '—';
    container.querySelector('#detail-order-no').textContent = error.受注番号 || '—';
    container.querySelector('#detail-error-code').textContent = error.エラーコード || '—';
    container.querySelector('#detail-error-msg').textContent = error.エラーメッセージ || '—';
    container.querySelector('#detail-error-detail').textContent = error.エラー詳細 || '—';
    container.querySelector('#detail-severity').textContent = error.重要度 || '—';
    container.querySelector('#detail-status').value = error.ステータス || '未対応';
    container.querySelector('#detail-category').value = error.エラー種別 || '';
    container.querySelector('#detail-assignee').value = error.対応者ID || '';
    container.querySelector('#detail-comment').value = error.対応コメント || '';

    container.querySelector('#detail-panel').style.display = 'flex';
  }

  function hideDetail() {
    container.querySelector('#detail-panel').style.display = 'none';
    selectedErrorId = null;
  }

  // ========== 4. 検索フィルタ ==========
  function applyFilters() {
    const orderNo = container.querySelector('#filter-order-no').value.toLowerCase();
    const errorCode = container.querySelector('#filter-error-code').value.toLowerCase();
    const severity = container.querySelector('#filter-severity').value;
    const status = container.querySelector('#filter-status').value;

    const filtered = errorLogRecords.filter(e => {
      const matchOrder = !orderNo || (e.受注番号 || '').toLowerCase().includes(orderNo);
      const matchCode = !errorCode || (e.エラーコード || '').toLowerCase().includes(errorCode);
      const matchSeverity = !severity || e.重要度 === severity;
      const matchStatus = !status || e.ステータス === status;
      return matchOrder && matchCode && matchSeverity && matchStatus;
    });

    allErrors = filtered;
    renderErrors(allErrors);
    updateKPIs();
  }

  // ========== 5. CSV エクスポート ==========
  function exportCSV() {
    const headers = ['受注ID', '受注番号', 'エラーコード', 'エラーメッセージ', '重要度', 'ステータス', '発生日時'];
    const rows = allErrors.map(e => [
      e.受注データID || '',
      e.受注番号 || '',
      e.エラーコード || '',
      e.エラーメッセージ || '',
      e.重要度 || '',
      e.ステータス || '',
      e.作成日時 ? new Date(e.作成日時).toLocaleString('ja-JP') : ''
    ]);

    const csv = '\uFEFF' + [headers, ...rows].map(r => r.map(c => `"${(c || '').replace(/"/g, '""')}"`).join(',')).join('\n');
    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `error-log-${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  }

  // ========== 6. 初期化 ==========
  renderErrors(allErrors);
  updateKPIs();

  // ========== 7. イベントリスナー ==========
  container.querySelector('#btn-search').addEventListener('click', applyFilters);
  container.querySelector('#btn-export').addEventListener('click', exportCSV);

  container.querySelector('#btn-close-detail').addEventListener('click', hideDetail);

  container.querySelector('#error-tbody').addEventListener('click', e => {
    const tr = e.target.closest('tr');
    if (tr) showDetail(tr.dataset.id);
  });

  container.querySelector('#btn-save-detail').addEventListener('click', async () => {
    if (!selectedErrorId) return;
    const error = allErrors.find(e => e.エラーログID === selectedErrorId);
    if (!error) return;

    error.ステータス = container.querySelector('#detail-status').value;
    error.エラー分類 = container.querySelector('#detail-category').value;
    error.対応者ID = container.querySelector('#detail-assignee').value;
    error.対応コメント = container.querySelector('#detail-comment').value;

    const saved = await window.aivicApi.update(errorLogTable.tableName, selectedErrorId, {
      ステータス: error.ステータス,
      エラー分類: error.エラー分類,
      対応者ID: error.対応者ID,
      対応コメント: error.対応コメント
    });

    if (saved) {
      renderErrors(allErrors);
      updateKPIs();
      hideDetail();
    }
  });

  container.querySelector('#btn-notify').addEventListener('click', () => {
    if (!selectedErrorId) return;
    alert('通知を送信しました');
    // 実装: 通知送信 API 呼び出し
  });

  container.querySelector('#btn-validate').addEventListener('click', () => {
    alert('バリデーション実行を開始しました');
    // 実装: バリデーション実行 API 呼び出し
  });

  container.querySelector('#btn-bulk-notify').addEventListener('click', () => {
    alert('一括通知を送信しました');
    // 実装: 一括通知 API 呼び出し
  });

  container.querySelector('#btn-to-integration').addEventListener('click', () => {
    window.showScreen('scr-1781408509581');
  });

  container.querySelector('#btn-view-rule').addEventListener('click', () => {
    window.showScreen('scr-1781408640983');
  });

  container.querySelector('#btn-view-history').addEventListener('click', () => {
    window.showScreen('scr-1781408601476');
  });
}

function(container, apiUrl, tables) {
  const tbody = container.querySelector("#error-log-tbody");
  const detailPanel = container.querySelector("#detail-panel");
  const noSelection = container.querySelector("#no-selection");
  const summaryChart = container.querySelector("#summary-chart");
  let allLogs = [];
  let selectedLog = null;

  // 1. ログ再描画関数
  function renderLogs(logs) {
    if (logs.length === 0) {
      tbody.innerHTML = '<tr style="background: var(--bg-main);"><td colspan="4" style="padding: 16px; text-align: center; color: var(--text-muted);">該当するエラーログがありません</td></tr>';
      return;
    }

    tbody.innerHTML = logs.map(log => {
      const severity = log.重要度 || 'INFO';
      const severityColor = severity === 'CRITICAL' ? '#ff5252' : severity === 'ERROR' ? '#ff9800' : severity === 'WARNING' ? '#ffc107' : '#4caf50';
      const timestamp = log.発生日時 ? new Date(log.発生日時).toLocaleString('ja-JP') : '-';

      return `<tr data-id="${log.エラーログID || ''}" class="error-log-row" style="cursor: pointer; border-bottom: 1px solid rgba(255,255,255,0.08); transition: background 0.2s;">
        <td style="padding: 8px; color: var(--text);">${timestamp}</td>
        <td style="padding: 8px; color: var(--text); font-family: monospace; font-weight: 500;">${log.エラーコード || '-'}</td>
        <td style="padding: 8px;">
          <span style="display: inline-block; padding: 2px 6px; border-radius: 3px; font-size: 11px; background: ${severityColor}20; color: ${severityColor}; font-weight: 600;">${severity}</span>
        </td>
        <td style="padding: 8px; color: var(--text); font-size: 11px; font-family: monospace;">${(log.受注データID || '-').substring(0, 8)}...</td>
      </tr>`;
    }).join("");

    // 行クリックで詳細表示
    container.querySelectorAll(".error-log-row").forEach(row => {
      row.addEventListener("click", () => {
        const logId = row.dataset.id;
        selectedLog = logs.find(l => l.エラーログID === logId);
        if (selectedLog) showDetail(selectedLog);
      });
    });
  }

  // 2. 詳細表示関数
  function showDetail(log) {
    detailPanel.style.display = "block";
    noSelection.style.display = "none";

    container.querySelector("#detail-log-id").textContent = log.エラーログID || '-';
    container.querySelector("#detail-order-id").textContent = log.受注データID || '-';
    container.querySelector("#detail-timestamp").textContent = log.発生日時 ? new Date(log.発生日時).toLocaleString('ja-JP') : '-';
    container.querySelector("#detail-error-code").textContent = log.エラーコード || '-';
    container.querySelector("#detail-severity").textContent = log.重要度 || '-';
    container.querySelector("#detail-message").textContent = log.エラーメッセージ || '-';
    container.querySelector("#detail-error-detail").textContent = log.エラー詳細 || '-';
    container.querySelector("#detail-error-type").textContent = log.エラー種別 || '-';
    container.querySelector("#detail-module").textContent = log.発生モジュール || '-';
    container.querySelector("#detail-status").value = log.ステータス || '未対応';
    container.querySelector("#detail-comment").value = log.対応コメント || '';
  }

  // 3. 集計グラフ描画
  function renderSummary(logs) {
    const severityCounts = {};
    logs.forEach(log => {
      const sev = log.重要度 || 'INFO';
      severityCounts[sev] = (severityCounts[sev] || 0) + 1;
    });

    const ctx = summaryChart.getContext("2d");
    const width = summaryChart.width;
    const height = summaryChart.height;
    ctx.clearRect(0, 0, width, height);

    const severities = Object.keys(severityCounts);
    const counts = Object.values(severityCounts);
    const colors = {
      'CRITICAL': '#ff5252',
      'ERROR': '#ff9800',
      'WARNING': '#ffc107',
      'INFO': '#4caf50'
    };

    const barWidth = width / (severities.length * 1.5);
    const maxCount = Math.max(...counts, 1);
    const padding = 20;

    severities.forEach((sev, idx) => {
      const count = counts[idx];
      const barHeight = ((count / maxCount) * (height - padding * 2));
      const x = padding + idx * (barWidth * 1.5);
      const y = height - padding - barHeight;

      ctx.fillStyle = colors[sev] || '#999';
      ctx.fillRect(x, y, barWidth, barHeight);

      ctx.fillStyle = '#d0e4ff';
      ctx.font = '11px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText(count, x + barWidth / 2, height - 5);

      ctx.fillStyle = '#9fb0d1';
      ctx.font = '10px sans-serif';
      ctx.fillText(sev, x + barWidth / 2, 15);
    });

    // 統計更新
    const pending = logs.filter(l => l.ステータス === '未対応').length;
    container.querySelector("#stat-total").textContent = logs.length;
    container.querySelector("#stat-pending").textContent = pending;
  }

  // 4. フィルタリング関数
  function applyFilters() {
    const dateFrom = container.querySelector("#filter-date-from").value;
    const dateTo = container.querySelector("#filter-date-to").value;
    const errorCode = container.querySelector("#filter-error-code").value.toUpperCase();
    const orderId = container.querySelector("#filter-order-id").value;
    const channel = container.querySelector("#filter-channel").value;
    const status = container.querySelector("#filter-status").value;

    let filtered = allLogs.filter(log => {
      if (dateFrom && new Date(log.発生日時) < new Date(dateFrom)) return false;
      if (dateTo && new Date(log.発生日時) > new Date(dateTo + 'T23:59:59')) return false;
      if (errorCode && !(log.エラーコード || '').includes(errorCode)) return false;
      if (orderId && !(log.受注データID || '').includes(orderId)) return false;
      if (channel && log.チャネル !== channel) return false;
      if (status && log.ステータス !== status) return false;
      return true;
    });

    renderLogs(filtered);
    renderSummary(filtered);
  }

  // 5. 初期データ読み込み
  async function loadData() {
    const logs = await window.aivicApi.list(0);
    if (logs) {
      allLogs = logs;
      renderLogs(allLogs);
      renderSummary(allLogs);
    }
  }

  // 6. イベントリスナー登録
  container.querySelector("#btn-search").addEventListener("click", applyFilters);

  container.querySelector("#btn-reset").addEventListener("click", () => {
    container.querySelector("#filter-date-from").value = '';
    container.querySelector("#filter-date-to").value = '';
    container.querySelector("#filter-error-code").value = '';
    container.querySelector("#filter-order-id").value = '';
    container.querySelector("#filter-channel").value = '';
    container.querySelector("#filter-status").value = '';
    renderLogs(allLogs);
    renderSummary(allLogs);
  });

  container.querySelector("#btn-close-detail").addEventListener("click", () => {
    detailPanel.style.display = "none";
    noSelection.style.display = "flex";
    selectedLog = null;
  });

  container.querySelector("#btn-update-status").addEventListener("click", async () => {
    if (!selectedLog) return;
    const newStatus = container.querySelector("#detail-status").value;
    const comment = container.querySelector("#detail-comment").value;

    const updated = await window.aivicApi.update(0, selectedLog.エラーログID, {
      ステータス: newStatus,
      対応コメント: comment
    });

    if (updated) {
      selectedLog.ステータス = newStatus;
      selectedLog.対応コメント = comment;
      allLogs = allLogs.map(l => l.エラーログID === selectedLog.エラーログID ? selectedLog : l);
      applyFilters();
      alert("ステータスを更新しました");
    }
  });

  // 初期化
  loadData();
}

function(container, apiUrl, tables) {
  // テーブルインデックス: エラーログ = 0
  const errorTableIndex = 0;
  const timelineEl = container.querySelector("#error-timeline");
  const detailModal = container.querySelector("#detail-modal");
  const assignModal = container.querySelector("#assign-modal");
  const detailContent = container.querySelector("#detail-content");

  let currentErrorId = null;
  let allErrors = [];

  // 優先度の色付け
  function getPriorityColor(priority) {
    const map = {
      "CRITICAL": "#ff3333",
      "ERROR": "#ff6a00",
      "WARNING": "#ffa500",
      "INFO": "#4caf50"
    };
    return map[priority] || "#999";
  }

  // ステータスの色付け
  function getStatusColor(status) {
    const map = {
      "未対応": "#ff6a00",
      "対応中": "#ffa500",
      "解決済み": "#4caf50"
    };
    return map[status] || "#999";
  }

  // KPI 更新
  function updateKpi(errors) {
    const pending = errors.filter(e => e.ステータス === "未対応").length;
    const inProgress = errors.filter(e => e.ステータス === "対応中").length;
    const resolved = errors.filter(e => e.ステータス === "解決済み").length;

    container.querySelector("[data-testid='kpi-pending']").textContent = pending;
    container.querySelector("[data-testid='kpi-in-progress']").textContent = inProgress;
    container.querySelector("[data-testid='kpi-resolved']").textContent = resolved;
  }

  // タイムラインレンダリング
  function renderTimeline(errors) {
    timelineEl.innerHTML = errors.map(err => {
      const priorityColor = getPriorityColor(err.重要度);
      const statusColor = getStatusColor(err.ステータス);
      const timestamp = new Date(err.発生日時).toLocaleString('ja-JP');

      return `
        <div class="card" style="padding: 1rem; border-left: 4px solid ${priorityColor}; cursor: pointer; transition: all 0.2s;" data-error-id="${err.エラーログID}">
          <div style="display: flex; justify-content: space-between; align-items: flex-start; gap: 1rem;">
            <div style="flex: 1;">
              <div style="display: flex; align-items: center; gap: 0.5rem; margin-bottom: 0.3rem;">
                <span style="font-weight: 700; color: var(--text); font-size: 0.95rem;">${err.エラーコード}</span>
                <span style="font-size: 0.75rem; background: ${statusColor}; color: #fff; padding: 0.2rem 0.5rem; border-radius: 0.2rem;">${err.ステータス}</span>
                <span style="font-size: 0.75rem; background: ${priorityColor}; color: #fff; padding: 0.2rem 0.5rem; border-radius: 0.2rem;">${err.重要度}</span>
              </div>
              <div style="font-size: 0.875rem; color: var(--text); margin-bottom: 0.3rem;">受注: <strong>${err.受注番号 || "N/A"}</strong></div>
              <div style="font-size: 0.875rem; color: var(--text-muted); margin-bottom: 0.3rem;">${err.エラーメッセージ}</div>
              <div style="display: flex; gap: 1rem; font-size: 0.75rem; color: var(--text-muted);">
                <span>分類: ${err.エラー種別}</span>
                <span>責任者: ${err.対応者ID || "未割当"}</span>
                <span>${timestamp}</span>
              </div>
            </div>
            <button class="action-btn secondary view-detail-btn" data-error-id="${err.エラーログID}" style="padding: 0.4rem 0.8rem; font-size: 0.75rem; white-space: nowrap;">詳細</button>
          </div>
        </div>
      `;
    }).join("");
  }

  // フィルタリング
  function applyFilters() {
    const responsible = container.querySelector("[data-testid='filter-responsible']").value;
    const category = container.querySelector("[data-testid='filter-category']").value;
    const priority = container.querySelector("[data-testid='filter-priority']").value;
    const status = container.querySelector("[data-testid='filter-status']").value;
    const dateFrom = container.querySelector("[data-testid='filter-date-from']").value;

    let filtered = allErrors;

    if (responsible) {
      filtered = filtered.filter(e => (e.対応者ID || "").includes(responsible));
    }
    if (category) {
      filtered = filtered.filter(e => e.エラー種別 === category);
    }
    if (priority) {
      filtered = filtered.filter(e => e.重要度 === priority);
    }
    if (status) {
      filtered = filtered.filter(e => e.ステータス === status);
    }
    if (dateFrom) {
      const fromDate = new Date(dateFrom);
      filtered = filtered.filter(e => new Date(e.発生日時) >= fromDate);
    }

    // 新しい順にソート
    filtered.sort((a, b) => new Date(b.発生日時) - new Date(a.発生日時));

    renderTimeline(filtered);
    updateKpi(filtered);
  }

  // 詳細モーダルを開く
  function openDetailModal(errorId) {
    const error = allErrors.find(e => e.エラーログID === errorId);
    if (!error) return;

    currentErrorId = errorId;
    const timestamp = new Date(error.発生日時).toLocaleString('ja-JP');

    detailContent.innerHTML = `
      <div style="display: grid; gap: 0.75rem;">
        <div>
          <div style="font-size: 0.75rem; color: var(--text-muted); font-weight: 600;">エラーコード</div>
          <div style="font-size: 1rem; color: var(--text); font-weight: 600;">${error.エラーコード}</div>
        </div>
        <div>
          <div style="font-size: 0.75rem; color: var(--text-muted); font-weight: 600;">受注番号</div>
          <div style="font-size: 1rem; color: var(--text);">${error.受注番号 || "N/A"}</div>
        </div>
        <div>
          <div style="font-size: 0.75rem; color: var(--text-muted); font-weight: 600;">エラーメッセージ</div>
          <div style="font-size: 0.875rem; color: var(--text); background: rgba(0,0,0,0.2); padding: 0.75rem; border-radius: 0.25rem; word-break: break-word;">${error.エラーメッセージ}</div>
        </div>
        <div>
          <div style="font-size: 0.75rem; color: var(--text-muted); font-weight: 600;">エラー詳細</div>
          <div style="font-size: 0.875rem; color: var(--text); background: rgba(0,0,0,0.2); padding: 0.75rem; border-radius: 0.25rem; word-break: break-word; max-height: 150px; overflow-y: auto;">${error.エラー詳細 || "詳細情報なし"}</div>
        </div>
        <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 0.75rem;">
          <div>
            <div style="font-size: 0.75rem; color: var(--text-muted); font-weight: 600;">重要度</div>
            <div style="font-size: 0.875rem; color: var(--text);">${error.重要度}</div>
          </div>
          <div>
            <div style="font-size: 0.75rem; color: var(--text-muted); font-weight: 600;">ステータス</div>
            <div style="font-size: 0.875rem; color: var(--text);">${error.ステータス}</div>
          </div>
        </div>
        <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 0.75rem;">
          <div>
            <div style="font-size: 0.75rem; color: var(--text-muted); font-weight: 600;">エラー種別</div>
            <div style="font-size: 0.875rem; color: var(--text);">${error.エラー種別}</div>
          </div>
          <div>
            <div style="font-size: 0.75rem; color: var(--text-muted); font-weight: 600;">発生モジュール</div>
            <div style="font-size: 0.875rem; color: var(--text);">${error.発生モジュール}</div>
          </div>
        </div>
        <div>
          <div style="font-size: 0.75rem; color: var(--text-muted); font-weight: 600;">発生日時</div>
          <div style="font-size: 0.875rem; color: var(--text);">${timestamp}</div>
        </div>
        <div>
          <div style="font-size: 0.75rem; color: var(--text-muted); font-weight: 600;">対応者</div>
          <div style="font-size: 0.875rem; color: var(--text);">${error.対応者ID || "未割当"}</div>
        </div>
        <div>
          <div style="font-size: 0.75rem; color: var(--text-muted); font-weight: 600;">対応コメント</div>
          <div style="font-size: 0.875rem; color: var(--text);">${error.対応コメント || "コメントなし"}</div>
        </div>
      </div>
    `;

    detailModal.removeAttribute("hidden");
  }

  // 割り当てモーダルを開く
  function openAssignModal() {
    detailModal.setAttribute("hidden", "");
    assignModal.removeAttribute("hidden");
    container.querySelector("#assign-user").value = "";
    container.querySelector("#assign-comment").value = "";
  }

  // 割り当てを確認
  async function confirmAssign() {
    const userId = container.querySelector("#assign-user").value;
    const comment = container.querySelector("#assign-comment").value;

    if (!userId) {
      alert("対応者を選択してください");
      return;
    }

    const error = allErrors.find(e => e.エラーログID === currentErrorId);
    if (!error) return;

    // API で更新
    const updated = await window.aivicApi.update(errorTableIndex, currentErrorId, {
      対応者ID: userId,
      対応コメント: comment,
      ステータス: "対応中"
    });

    if (updated) {
      // ローカルデータも更新
      const idx = allErrors.findIndex(e => e.エラーログID === currentErrorId);
      if (idx >= 0) {
        allErrors[idx].対応者ID = userId;
        allErrors[idx].対応コメント = comment;
        allErrors[idx].ステータス = "対応中";
      }

      assignModal.setAttribute("hidden", "");
      applyFilters();
    }
  }

  // イベントリスナー
  container.querySelector("[data-testid='search-button']").addEventListener("click", applyFilters);

  container.querySelector("[data-testid='reset-button']").addEventListener("click", () => {
    container.querySelector("[data-testid='filter-responsible']").value = "";
    container.querySelector("[data-testid='filter-category']").value = "";
    container.querySelector("[data-testid='filter-priority']").value = "";
    container.querySelector("[data-testid='filter-status']").value = "";
    container.querySelector("[data-testid='filter-date-from']").value = "";
    applyFilters();
  });

  container.querySelector("[data-testid='refresh-button']").addEventListener("click", async () => {
    allErrors = await window.aivicApi.list(errorTableIndex) || [];
    applyFilters();
  });

  container.querySelector("#close-detail").addEventListener("click", () => {
    detailModal.setAttribute("hidden", "");
  });

  container.querySelector("#close-detail-btn").addEventListener("click", () => {
    detailModal.setAttribute("hidden", "");
  });

  container.querySelector("#assign-button").addEventListener("click", openAssignModal);

  container.querySelector("#cancel-assign").addEventListener("click", () => {
    assignModal.setAttribute("hidden", "");
    openDetailModal(currentErrorId);
  });

  container.querySelector("#confirm-assign").addEventListener("click", confirmAssign);

  // タイムラインの詳細ボタン
  container.addEventListener("click", e => {
    const detailBtn = e.target.closest(".view-detail-btn");
    if (detailBtn) {
      const errorId = detailBtn.dataset.errorId;
      openDetailModal(errorId);
    }
  });

  // 初期データ読み込み
  (async () => {
    allErrors = await window.aivicApi.list(errorTableIndex) || [];
    applyFilters();
  })();
}

function(container, apiUrl, tables) {
  // テーブルインデックス
  const TABLE_INTEGRATION_HISTORY = 0;   // 基幹システム連携履歴
  const TABLE_INTEGRATION_REFLECTION = 1; // 連携反映状況
  const TABLE_ERROR_LOG = 2;              // エラーログ
  const TABLE_ERROR_CLASSIFICATION = 3;   // エラー分類マスタ
  const TABLE_LOGIN_USER = 4;             // ログインユーザー
  const TABLE_USER_PERMISSION = 5;        // ユーザー権限
  const TABLE_APPROVED_ORDERS = 6;        // 承認済み受注
  const TABLE_MONTHLY_VARIANCE = 7;       // 月次差異検証

  // DOM 要素キャッシュ
  const userNameEl = container.querySelector('[data-testid="user-name"]');
  const userRoleEl = container.querySelector('[data-testid="user-role"]');
  const kpiTotalEl = container.querySelector('[data-testid="kpi-total-count"]');
  const kpiSuccessEl = container.querySelector('[data-testid="kpi-success-count"]');
  const kpiErrorEl = container.querySelector('[data-testid="kpi-error-count"]');
  const kpiRateEl = container.querySelector('[data-testid="kpi-success-rate"]');
  const integrationTbody = container.querySelector('#integration-tbody');
  const timelineContainer = container.querySelector('#timeline-container');
  const errorDetailList = container.querySelector('#error-detail-list');
  const errorChart = container.querySelector('#error-chart');
  const executeBtn = container.querySelector('[data-testid="execute-button"]');
  const retryBtn = container.querySelector('[data-testid="retry-button"]');
  const detailBtn = container.querySelector('[data-testid="detail-button"]');
  const executeModal = container.querySelector('#execute-modal');
  const errorDetailModal = container.querySelector('#error-detail-modal');
  const modalCancelBtn = container.querySelector('[data-testid="modal-cancel"]');
  const modalConfirmBtn = container.querySelector('[data-testid="modal-confirm"]');
  const errorModalCloseBtn = container.querySelector('[data-testid="error-modal-close"]');

  let currentIntegrationData = [];
  let currentErrorData = [];
  let currentReflectionData = [];

  // ===== 1. ユーザー情報表示 =====
  function displayUserInfo() {
    const users = tables[TABLE_LOGIN_USER]?.records || [];
    const currentUser = users[0]; // 実装では認証情報から取得
    if (currentUser) {
      userNameEl.textContent = currentUser.ユーザー名 || '-';
      const perms = tables[TABLE_USER_PERMISSION]?.records || [];
      const userPerm = perms.find(p => p.ユーザーID === currentUser.ユーザーID);
      userRoleEl.textContent = userPerm?.権限名 || '-';
    }
  }

  // ===== 2. KPI 更新 =====
  function updateKPI() {
    const integrations = currentIntegrationData;
    const totalCount = integrations.reduce((sum, r) => sum + (r.送信データ件数 || 0), 0);
    const successCount = integrations.reduce((sum, r) => sum + (r.成功件数 || 0), 0);
    const failureCount = integrations.reduce((sum, r) => sum + (r.失敗件数 || 0), 0);
    const rate = totalCount > 0 ? Math.round((successCount / totalCount) * 100) : 0;

    kpiTotalEl.textContent = totalCount.toLocaleString();
    kpiSuccessEl.textContent = successCount.toLocaleString();
    kpiErrorEl.textContent = failureCount.toLocaleString();
    kpiRateEl.textContent = rate + '%';
  }

  // ===== 3. 連携実行ステータステーブル再描画 =====
  function renderIntegrationStatus() {
    const rows = currentIntegrationData.slice(0, 20); // 最新20件
    integrationTbody.innerHTML = rows.map(r => {
      const statusColor = r.処理ステータス === '成功' ? '#4caf50' : r.処理ステータス === '失敗' ? '#f44336' : '#ff9800';
      return `
        <tr style="background: var(--bg-card); border-bottom: 1px solid rgba(255,255,255,0.05); hover: background var(--bg-main);" data-id="${r.連携履歴ID}">
          <td style="padding: 0.5rem 0.75rem; color: var(--text-muted); font-family: monospace; font-size: 0.75rem;">${(r.連携履歴ID || '').substring(0, 8)}</td>
          <td style="padding: 0.5rem 0.75rem; color: var(--text);">${r.連携種別 || '-'}</td>
          <td style="padding: 0.5rem 0.75rem; text-align: center; color: var(--text);">${r.送信データ件数 || 0}</td>
          <td style="padding: 0.5rem 0.75rem; text-align: center; color: #4caf50; font-weight: 600;">${r.成功件数 || 0}</td>
          <td style="padding: 0.5rem 0.75rem; text-align: center; color: #f44336; font-weight: 600;">${r.失敗件数 || 0}</td>
          <td style="padding: 0.5rem 0.75rem; text-align: center;">
            <span style="display: inline-block; padding: 0.25rem 0.5rem; border-radius: 3px; background: ${statusColor}20; color: ${statusColor}; font-size: 0.75rem; font-weight: 600;">${r.処理ステータス || '-'}</span>
          </td>
        </tr>
      `;
    }).join('');
    if (rows.length === 0) {
      integrationTbody.innerHTML = '<tr style="background: var(--bg-card);"><td colspan="6" style="padding: 1rem; text-align: center; color: var(--text-muted);">データなし</td></tr>';
    }
  }

  // ===== 4. エラー分類別集計グラフ =====
  function renderErrorChart() {
    const ctx = errorChart.getContext('2d');
    const errorCounts = {};
    currentErrorData.forEach(e => {
      const code = e.エラーコード || 'その他';
      errorCounts[code] = (errorCounts[code] || 0) + 1;
    });
    const labels = Object.keys(errorCounts).slice(0, 5);
    const data = labels.map(l => errorCounts[l]);
    const colors = ['#f44336', '#ff9800', '#ffc107', '#ff5722', '#e91e63'];

    ctx.clearRect(0, 0, errorChart.width, errorChart.height);
    const barWidth = errorChart.width / (labels.length + 1);
    const maxValue = Math.max(...data, 1);
    const scale = (errorChart.height - 40) / maxValue;

    labels.forEach((label, i) => {
      const x = (i + 0.5) * barWidth;
      const height = data[i] * scale;
      const y = errorChart.height - 30 - height;
      ctx.fillStyle = colors[i] || '#999';
      ctx.fillRect(x - barWidth * 0.35, y, barWidth * 0.7, height);
      ctx.fillStyle = '#9fb0d1';
      ctx.font = '10px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText(label.substring(0, 6), x, errorChart.height - 10);
      ctx.fillText(data[i], x, y - 5);
    });
  }

  // ===== 5. エラー詳細リスト =====
  function renderErrorDetail() {
    const topErrors = currentErrorData.slice(0, 5);
    errorDetailList.innerHTML = topErrors.map(e => `
      <div style="padding: 0.5rem; background: rgba(244,67,54,0.1); border-left: 2px solid #f44336; border-radius: 2px;">
        <div style="font-weight: 600; color: var(--text);">${e.エラーコード || '-'}</div>
        <div style="font-size: 0.75rem; color: var(--text-muted); margin-top: 0.25rem;">${e.エラーメッセージ?.substring(0, 50) || '-'}</div>
      </div>
    `).join('');
    if (topErrors.length === 0) {
      errorDetailList.innerHTML = '<div style="color: var(--text-muted);">エラーなし</div>';
    }
  }

  // ===== 6. 連携反映状況タイムライン =====
  function renderTimeline() {
    const reflections = currentReflectionData.slice(0, 10);
    timelineContainer.innerHTML = reflections.map(r => {
      const statusColor = r.反映ステータス === '成功' ? '#4caf50' : r.反映ステータス === '失敗' ? '#f44336' : '#ff9800';
      const time = r.反映完了日時 ? new Date(r.反映完了日時).toLocaleString('ja-JP') : '-';
      return `
        <div style="display: flex; gap: 0.75rem; padding: 0.75rem; background: var(--bg-main); border-radius: 4px; border-left: 3px solid ${statusColor};">
          <div style="flex-shrink: 0; width: 3px; background: ${statusColor}; border-radius: 2px;"></div>
          <div style="flex: 1; min-width: 0;">
            <div style="font-weight: 600; color: var(--text);">${r.連携バッチ番号 || '-'}</div>
            <div style="font-size: 0.75rem; color: var(--text-muted); margin-top: 0.25rem;">
              受信: ${r.受信件数 || 0} | 成功: ${r.反映成功件数 || 0} | 失敗: ${r.反映失敗件数 || 0}
            </div>
            <div style="font-size: 0.75rem; color: var(--text-muted); margin-top: 0.25rem;">${time}</div>
          </div>
        </div>
      `;
    }).join('');
    if (reflections.length === 0) {
      timelineContainer.innerHTML = '<div style="color: var(--text-muted); padding: 0.5rem;">データなし</div>';
    }
  }

  // ===== 7. 全体更新 =====
  async function refreshAll() {
    try {
      currentIntegrationData = (await window.aivicApi.list(TABLE_INTEGRATION_HISTORY)) || [];
      currentReflectionData = (await window.aivicApi.list(TABLE_INTEGRATION_REFLECTION)) || [];
      currentErrorData = (await window.aivicApi.list(TABLE_ERROR_LOG)) || [];

      displayUserInfo();
      updateKPI();
      renderIntegrationStatus();
      renderErrorChart();
      renderErrorDetail();
      renderTimeline();
    } catch (e) {
      console.error('データ取得エラー:', e);
    }
  }

  // ===== 8. 連携実行ボタン =====
  executeBtn.addEventListener('click', () => {
    const approvedOrders = tables[TABLE_APPROVED_ORDERS]?.records || [];
    const count = approvedOrders.filter(o => o.連携ステータス === '未連携').length;
    container.querySelector('#modal-count').textContent = count;
    executeModal.removeAttribute('hidden');
  });

  modalConfirmBtn.addEventListener('click', async () => {
    executeModal.setAttribute('hidden', '');
    try {
      const result = await window.aivicApi.save(TABLE_INTEGRATION_HISTORY, {
        連携種別: '受注同期',
        連携方向: '送信',
        処理ステータス: '実行中',
        送信データ件数: 0,
        成功件数: 0,
        失敗件数: 0,
        実行開始日時: new Date().toISOString(),
        実行トリガー: '手動',
        リトライ回数: 0
      });
      if (result) {
        await refreshAll();
      }
    } catch (e) {
      console.error('連携実行エラー:', e);
    }
  });

  modalCancelBtn.addEventListener('click', () => {
    executeModal.setAttribute('hidden', '');
  });

  // ===== 9. 再実行ボタン =====
  retryBtn.addEventListener('click', async () => {
    const failedIntegrations = currentIntegrationData.filter(i => i.処理ステータス === '失敗');
    if (failedIntegrations.length === 0) {
      alert('再実行対象がありません');
      return;
    }
    try {
      for (const integration of failedIntegrations) {
        await window.aivicApi.update(TABLE_INTEGRATION_HISTORY, integration.連携履歴ID, {
          処理ステータス: '実行中',
          リトライ回数: (integration.リトライ回数 || 0) + 1
        });
      }
      await refreshAll();
    } catch (e) {
      console.error('再実行エラー:', e);
    }
  });

  // ===== 10. 詳細ボタン =====
  detailBtn.addEventListener('click', () => {
    const errorContent = container.querySelector('#error-detail-content');
    const summary = currentErrorData.slice(0, 10).map(e => `
      <div style="margin-bottom: 1rem; padding: 0.75rem; background: rgba(244,67,54,0.1); border-radius: 4px;">
        <div style="font-weight: 600; color: var(--text);">${e.エラーコード || '-'}</div>
        <div style="font-size: 0.875rem; color: var(--text); margin-top: 0.5rem;">${e.エラーメッセージ || '-'}</div>
        <div style="font-size: 0.75rem; color: var(--text-muted); margin-top: 0.5rem;">
          重要度: ${e.重要度 || '-'} | 種別: ${e.エラー種別 || '-'}
        </div>
      </div>
    `).join('');
    errorContent.innerHTML = summary || '<div style="color: var(--text-muted);">エラーなし</div>';
    errorDetailModal.removeAttribute('hidden');
  });

  errorModalCloseBtn.addEventListener('click', () => {
    errorDetailModal.setAttribute('hidden', '');
  });

  // ===== 11. 初期化 =====
  refreshAll();
  setInterval(refreshAll, 30000); // 30秒ごとに更新
}

function(container, apiUrl, tables) {
  // テーブルインデックス
  const HISTORY_TABLE = 0;  // 基幹システム連携履歴
  const ERROR_LOG_TABLE = 1; // エラーログ
  const VALIDATION_RESULT_TABLE = 2; // バリデーション結果

  let allHistoryRecords = [];
  let selectedHistoryId = null;

  // ========== 1. 再描画関数 ==========
  function renderTimeline(records) {
    const timelineList = container.querySelector("#timeline-list");
    if (!records || records.length === 0) {
      timelineList.innerHTML = '<div style="padding: 12px; color: var(--text-muted); font-size: 13px; text-align: center;">データなし</div>';
      return;
    }

    timelineList.innerHTML = records
      .sort((a, b) => new Date(b.実行開始日時 || 0) - new Date(a.実行開始日時 || 0))
      .map(r => {
        const statusColor = r.処理ステータス === '成功' ? '#4ade80' : r.処理ステータス === '失敗' ? '#ff6b6b' : '#fbbf24';
        const statusBg = r.処理ステータス === '成功' ? 'rgba(74,222,128,0.1)' : r.処理ステータス === '失敗' ? 'rgba(255,107,107,0.1)' : 'rgba(251,191,36,0.1)';
        const startTime = r.実行開始日時 ? new Date(r.実行開始日時).toLocaleString('ja-JP') : '—';
        return `
          <div class="timeline-item" data-id="${r.連携履歴ID || r.id}" style="padding: 10px; margin-bottom: 8px; border-left: 3px solid ${statusColor}; background: ${statusBg}; border-radius: 4px; cursor: pointer; transition: all 0.2s;" onmouseover="this.style.background='rgba(255,255,255,0.08)'" onmouseout="this.style.background='${statusBg}'">
            <div style="display: flex; justify-content: space-between; align-items: center; margin-bottom: 4px;">
              <span style="font-size: 13px; font-weight: 600; color: var(--text);">${r.連携種別 || '—'}</span>
              <span style="font-size: 11px; color: ${statusColor}; font-weight: 600; background: rgba(255,255,255,0.1); padding: 2px 6px; border-radius: 3px;">${r.処理ステータス || '—'}</span>
            </div>
            <div style="font-size: 11px; color: var(--text-muted); margin-bottom: 4px;">${startTime}</div>
            <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 6px; font-size: 11px;">
              <div>成功: <span style="color: #4ade80; font-weight: 600;">${r.成功件数 || 0}</span></div>
              <div>失敗: <span style="color: #ff6b6b; font-weight: 600;">${r.失敗件数 || 0}</span></div>
            </div>
          </div>
        `;
      })
      .join("");

    // イベントデリゲーション
    container.querySelectorAll(".timeline-item").forEach(el => {
      el.addEventListener("click", () => {
        selectedHistoryId = el.dataset.id;
        container.querySelectorAll(".timeline-item").forEach(e => e.style.opacity = "0.6");
        el.style.opacity = "1";
        renderDetailPanel(records.find(r => (r.連携履歴ID || r.id) === selectedHistoryId));
