            <div><span style="color: var(--text-muted);">ステータス:</span> <span style="color: var(--text); font-weight: 500;">${historyRecord.処理ステータス || '—'}</span></div>
            <div><span style="color: var(--text-muted);">処理時間:</span> <span style="color: var(--text); font-weight: 500;">${historyRecord.処理時間秒 || 0}秒</span></div>
          </div>
