            <div><span style="color: var(--text-muted);">実行終了:</span> <span style="color: var(--text); font-weight: 500; font-size: 11px;">${historyRecord.実行終了日時 ? new Date(historyRecord.実行終了日時).toLocaleString('ja-JP') : '—'}</span></div>
