          <div class="card" style="padding: 8px; text-align: center; border-left: 3px solid #ff6b6b;">
            <div style="font-size: 11px; color: var(--text-muted); margin-bottom: 2px;">失敗</div>
            <div style="font-size: 16px; font-weight: 600; color: #ff6b6b;">${historyRecord.失敗件数 || 0}</div>
          </div>
        </div>

        <!-- エラーメッセージ -->
        ${historyRecord.エラー詳細 ? `
          <div style="background: rgba(255,107,107,0.1); border: 1px solid rgba(255,107,107,0.3); border-radius: 4px; padding: 10px; margin-bottom: 12px;">
            <div style="font-size: 12px; font-weight: 600; color: #ff6b6b; margin-bottom: 4px;">エラー詳細</div>
            <div style="font-size: 12px; color: var(--text); word-break: break-word; max-height: 120px; overflow-y: auto;">${historyRecord.エラー詳細}</div>
          </div>
        ` : ''}

        <!-- リトライ情報 -->
        ${historyRecord.リトライ回数 > 0 ? `
          <div style="background: rgba(251,191,36,0.1); border: 1px solid rgba(251,191,36,0.3); border-radius: 4px; padding: 10px; margin-bottom: 12px;">
            <div style="font-size: 12px; font-weight: 600; color: #fbbf24; margin-bottom: 4px;">リトライ情報</div>
            <div style="font-size: 12px; color: var(--text);">
              <div>実行回数: <span style="font-weight: 600;">${historyRecord.リトライ回数}</span></div>
              <div>次回予定: <span style="font-weight: 600;">${historyRecord.リトライ予定日時 ? new Date(historyRecord.リトライ予定日時).toLocaleString('ja-JP') : '—'}</span></div>
            </div>
          </div>
        ` : ''}

        <!-- アクションボタン -->
        <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 8px; margin-top: 12px;">
          <button data-testid="detail-search-order" class="action-btn secondary" style="padding: 8px 12px; font-size: 12px;">受注ID検索</button>
          <button data-testid="detail-view-errors" class="action-btn" style="padding: 8px 12px; font-size: 12px;">エラー詳細</button>
        </div>
      </div>
    `;

    detailPanel.innerHTML = html;

    // ボタンイベント
    container.querySelector("[data-testid='detail-search-order']").addEventListener("click", () => {
      container.querySelector("#search-modal").removeAttribute("hidden");
    });

    container.querySelector("[data-testid='detail-view-errors']").addEventListener("click", () => {
      window.showScreen("scr-1781408467707");
    });
  }

  // ========== 3. KPI 更新 ==========
  function updateKPI(records) {
    const total = records.length;
    const success = records.filter(r => r.処理ステータス === '成功').length;
    const failure = records.filter(r => r.処理ステータス === '失敗').length;
    const warning = records.filter(r => r.処理ステータス === '部分成功').length;

    container.querySelector("#kpi-total").textContent = total;
    container.querySelector("#kpi-success").textContent = success;
    container.querySelector("#kpi-failure").textContent = failure;
    container.querySelector("#kpi-warning").textContent = warning;
  }

  // ========== 4. 初期データ読み込み ==========
  async function loadInitialData() {
    const historyRecords = tables[HISTORY_TABLE]?.records || [];
    allHistoryRecords = historyRecords;
    renderTimeline(historyRecords);
    updateKPI(historyRecords);
  }

  // ========== 5. 検索ボタン ==========
  container.querySelector("[data-testid='filter-search-button']").addEventListener("click", async () => {
    const startDate = container.querySelector("[data-testid='filter-start-date']").value;
    const endDate = container.querySelector("[data-testid='filter-end-date']").value;
    const status = container.querySelector("[data-testid='filter-status']").value;
    const errorClass = container.querySelector("[data-testid='filter-error-class']").value;

    let filtered = allHistoryRecords;

    if (startDate) {
      const start = new Date(startDate);
      filtered = filtered.filter(r => new Date(r.実行開始日時 || 0) >= start);
    }

    if (endDate) {
      const end = new Date(endDate);
      filtered = filtered.filter(r => new Date(r.実行開始日時 || 0) <= end);
    }

    if (status) {
      filtered = filtered.filter(r => r.処理ステータス === status);
    }

    if (errorClass) {
      filtered = filtered.filter(r => r.エラー詳細 && r.エラー詳細.includes(errorClass));
    }

    renderTimeline(filtered);
    updateKPI(filtered);
  });

  // ========== 6. 受注ID検索モーダル ==========
  container.querySelector("[data-testid='search-modal-cancel']").addEventListener("click", () => {
    container.querySelector("#search-modal").setAttribute("hidden", "");
  });

  container.querySelector("[data-testid='search-modal-ok']").addEventListener("click", () => {
    const orderId = container.querySelector("[data-testid='search-order-id']").value;
    if (!orderId) {
      alert("受注IDを入力してください");
      return;
    }
    // 受注ID検索処理（詳細画面へ遷移など）
    window.showScreen("scr-1781408467707");
    container.querySelector("#search-modal").setAttribute("hidden", "");
  });

  // ========== 7. 初期化 ==========
  loadInitialData();
}

function(container, apiUrl, tables) {
  // テーブルインデックス（バリデーション結果テーブルを想定）
  const validationResultTableIndex = 0;
  const errorLogTableIndex = 1;
  const notificationHistoryTableIndex = 2;

  // 1. 再描画関数
  function renderFailureList(rows) {
    const tbody = container.querySelector("#failure-list-tbody");
    tbody.innerHTML = rows.map(r => {
      const severityColor = r.重要度 === 'CRITICAL' ? '#ff6b6b' : r.重要度 === 'ERROR' ? '#ffa500' : '#4ecdc4';
      const severityLabel = r.重要度 === 'CRITICAL' ? '緊急' : r.重要度 === 'ERROR' ? 'エラー' : '警告';
      return `
        <tr data-id="${r.id}" style="border-bottom: 1px solid rgba(255,255,255,0.08); cursor: pointer; height: 36px;" class="failure-row">
          <td style="padding: 6px 8px; color: var(--text);">${r.受注番号 || '-'}</td>
          <td style="padding: 6px 8px; color: var(--text); font-size: 11px;">${r.エラー分類 || '-'}</td>
          <td style="padding: 6px 8px; text-align: center;">
            <span style="display: inline-block; background: ${severityColor}; color: #fff; padding: 2px 6px; border-radius: 2px; font-size: 10px; font-weight: 600;">${severityLabel}</span>
          </td>
          <td style="padding: 6px 8px; color: var(--text-muted); font-size: 11px;">${new Date(r.発生日時).toLocaleString('ja-JP').slice(0, 16)}</td>
        </tr>
      `;
    }).join("");

    // 行クリックで詳細表示
    container.querySelectorAll(".failure-row").forEach(row => {
      row.addEventListener("click", () => {
        const id = row.dataset.id;
        const record = rows.find(r => r.id === id);
        if (record) {
          showDetail(record);
        }
      });
    });
  }

  // 詳細パネルを表示
  function showDetail(record) {
    const detailPanel = container.querySelector("#detail-panel");
    container.querySelector("#detail-order-id").textContent = record.id || '-';
    container.querySelector("#detail-order-number").textContent = record.受注番号 || '-';
    container.querySelector("#detail-customer-name").textContent = record.顧客名 || '-';
    container.querySelector("#detail-amount").textContent = record.受注金額 ? `¥${record.受注金額.toLocaleString()}` : '-';
    container.querySelector("#detail-error-message").textContent = record.エラーメッセージ || '-';
    detailPanel.style.display = 'block';

    // 責任者を自動割り当て
    const categorySelect = container.querySelector("#notify-error-category");
    categorySelect.value = record.エラー分類 || '';
    autoAssignResponsible(record.エラー分類);
  }

  // 責任者を自動割り当て
  function autoAssignResponsible(errorCategory) {
    const responsibleSelect = container.querySelector("#notify-responsible");
    if (errorCategory === 'VAL_REQUIRED' || errorCategory === 'VAL_FORMAT') {
      responsibleSelect.value = 'resp-002'; // 品質管理部
    } else if (errorCategory === 'SYS_ERROR') {
      responsibleSelect.value = 'resp-003'; // システム部
    } else {
      responsibleSelect.value = 'resp-001'; // 営業部
    }
  }

  // 2. 初期データ読み込み
  if (tables[validationResultTableIndex] && tables[validationResultTableIndex].records) {
    renderFailureList(tables[validationResultTableIndex].records);
  }

  // 3. 検索ボタン
  container.querySelector("#btn-search").addEventListener("click", async () => {
    const categoryFilter = container.querySelector("#error-category-filter").value;
    const severityFilter = container.querySelector("#severity-filter").value;

    const rows = await window.aivicApi.list(validationResultTableIndex);
    if (!rows) return;

    const filtered = rows.filter(r => {
      const matchCategory = !categoryFilter || r.エラー分類 === categoryFilter;
      const matchSeverity = !severityFilter || r.重要度 === severityFilter;
      return matchCategory && matchSeverity;
    });

    renderFailureList(filtered);
  });

  // 4. リセットボタン
  container.querySelector("#btn-reset-button").addEventListener("click", async () => {
    container.querySelector("#error-category-filter").value = '';
    container.querySelector("#severity-filter").value = '';
    const rows = await window.aivicApi.list(validationResultTableIndex);
    if (rows) renderFailureList(rows);
  });

  // 5. 通知テンプレートプレビュー
  container.querySelector("#notify-template").addEventListener("change", (e) => {
    const templateId = e.target.value;
    const previewDiv = container.querySelector("#notify-preview");
    const templates = {
      'tpl-001': '【標準エラー通知】\n受注番号: ${受注番号}\nエラー内容: ${エラーメッセージ}\n対応をお願いします。',
      'tpl-002': '【緊急エスカレーション】\n受注ID: ${id}\n重要度: 緊急\n即座の対応が必要です。',
      'tpl-003': '【定期レポート】\n本日のエラー件数: ${件数}\n詳細は管理画面をご確認ください。'
    };
    previewDiv.textContent = templates[templateId] || 'テンプレートを選択してください';
  });

  // 6. 即時通知ボタン
  container.querySelector("#btn-notify-now").addEventListener("click", async () => {
    const responsible = container.querySelector("#notify-responsible").value;
    const channels = [];
    if (container.querySelector("#channel-email").checked) channels.push('email');
    if (container.querySelector("#channel-sms").checked) channels.push('sms');
    if (container.querySelector("#channel-system").checked) channels.push('system');
    const template = container.querySelector("#notify-template").value;

    if (!responsible || channels.length === 0 || !template) {
      alert('責任者、チャネル、テンプレートを選択してください');
      return;
    }

    const notificationData = {
      責任者ID: responsible,
      通知チャネル: channels.join(','),
      通知テンプレート: template,
      送信日時: new Date().toISOString(),
      通知ステータス: '送信済'
    };

    const saved = await window.aivicApi.save(notificationHistoryTableIndex, notificationData);
    if (saved) {
      alert('通知を送信しました');
    }
  });

  // 7. スケジュール保存
  container.querySelector("#btn-schedule-save").addEventListener("click", async () => {
    const frequency = container.querySelector("#schedule-frequency").value;
    const time = container.querySelector("#schedule-time").value;

    if (!frequency || !time) {
      alert('実行周期と実行時刻を選択してください');
      return;
    }

    alert(`スケジュール保存: ${frequency} ${time}`);
  });

  // 8. ルール保存
  container.querySelector("#btn-rule-save").addEventListener("click", async () => {
    const ruleName = container.querySelector("#rule-name").value;
    const ruleSeverity = container.querySelector("#rule-severity").value;
    const ruleEnabled = container.querySelector("#rule-enabled").checked;

    if (!ruleName || !ruleSeverity) {
      alert('ルール名と条件を入力してください');
      return;
    }

    alert(`ルール保存: ${ruleName} (${ruleSeverity}) - ${ruleEnabled ? '有効' : '無効'}`);
  });

  // 9. エラー分類選択時に責任者を自動割り当て
  container.querySelector("#notify-error-category").addEventListener("change", (e) => {
    autoAssignResponsible(e.target.value);
  });
}

function(container, apiUrl, tables) {
  // テーブルインデックス: 0=バリデーション結果, 1=エラーログ, 2=責任者マスタ
  const validationResultIndex = 0;
  const errorLogIndex = 1;
  const ownerIndex = 2;

  let currentErrors = [];
  let selectedErrorId = null;

  // 1. エラー一覧再描画関数
  function renderErrors(errors) {
    const tbody = container.querySelector("#error-tbody");
    if (!errors || errors.length === 0) {
      tbody.innerHTML = `<tr style="border-bottom: 1px solid rgba(255,255,255,0.08);"><td colspan="3" style="padding: 0.4rem; text-align: center; color: var(--text-muted); font-size: 0.8rem;">エラーなし</td></tr>`;
      container.querySelector("#error-count").textContent = "0";
      return;
    }
    tbody.innerHTML = errors.map((err, idx) => `
      <tr style="border-bottom: 1px solid rgba(255,255,255,0.08); cursor: pointer;" data-error-id="${err.id || idx}" class="error-row">
        <td style="padding: 0.4rem; color: var(--text); font-size: 0.8rem;">${err.errorCode || "ERR_" + (idx + 1)}</td>
        <td style="padding: 0.4rem; color: var(--text); font-size: 0.8rem;">${err.errorField || "—"}</td>
        <td style="padding: 0.4rem; font-size: 0.8rem;">
          <span style="padding: 0.2rem 0.4rem; border-radius: 0.2rem; font-size: 0.75rem; font-weight: 600; ${
            err.severity === "CRITICAL" ? "background: #ff6a00; color: #fff;" :
            err.severity === "WARNING" ? "background: #ffa500; color: #000;" :
            "background: rgba(255,255,255,0.1); color: var(--text);"
          }">${err.severity || "INFO"}</span>
        </td>
      </tr>
    `).join("");
    container.querySelector("#error-count").textContent = errors.length;
  }

  // 2. 初期データ描画
  renderErrors(tables[errorLogIndex]?.records || []);
  currentErrors = tables[errorLogIndex]?.records || [];

  // 3. 検証実行ボタン
  container.querySelector("[data-testid='validate-button']").addEventListener("click", async () => {
    const progressDiv = container.querySelector("#validation-progress");
    progressDiv.style.display = "block";
    const progressBar = container.querySelector("#progress-bar");

    // プログレスアニメーション
    let progress = 0;
    const interval = setInterval(() => {
      progress += Math.random() * 30;
      if (progress > 90) progress = 90;
      progressBar.style.width = progress + "%";
    }, 200);

    // 検証実行（シミュレーション）
    await new Promise(r => setTimeout(r, 2000));
    clearInterval(interval);
    progressBar.style.width = "100%";

    // 結果表示
    container.querySelector("#status-badge").textContent = "検証完了";
    container.querySelector("#status-badge").style.color = "#4ade80";

    // エラーデータ取得
    const errors = await window.aivicApi.list(errorLogIndex);
    if (errors) {
      currentErrors = errors;
      renderErrors(errors);
    }

    setTimeout(() => {
      progressDiv.style.display = "none";
      progressBar.style.width = "0%";
    }, 1000);
  });

  // 4. エラーフィルタ
  container.querySelector("[data-testid='error-filter-select']").addEventListener("change", (e) => {
    const filterValue = e.target.value;
    let filtered = currentErrors;
    if (filterValue) {
      filtered = currentErrors.filter(err => {
        if (filterValue === "validation") return err.errorType === "バリデーションエラー";
        if (filterValue === "format") return err.errorType === "形式エラー";
        if (filterValue === "range") return err.errorType === "範囲エラー";
        if (filterValue === "required") return err.errorType === "必須項目エラー";
        return true;
      });
    }
    renderErrors(filtered);
  });

  // 5. エラー行クリックで詳細表示
  container.addEventListener("click", (e) => {
    const errorRow = e.target.closest(".error-row");
    if (errorRow) {
      const errorId = errorRow.dataset.errorId;
      const error = currentErrors.find((err, idx) => (err.id || idx) == errorId);
      if (error) {
        selectedErrorId = errorId;
        container.querySelector("#error-message").textContent = error.errorMessage || "—";
        container.querySelector("#error-value").textContent = error.errorValue || "—";
        container.querySelector("#detail-panel").style.display = "block";
      }
    }
  });

  // 6. タブ切り替え
  container.querySelectorAll(".detail-tab").forEach(tab => {
    tab.addEventListener("click", (e) => {
      const tabName = e.target.dataset.tab;
      container.querySelectorAll(".detail-tab").forEach(t => {
        t.style.color = t.dataset.tab === tabName ? "var(--text)" : "var(--text-muted)";
        t.style.borderBottomColor = t.dataset.tab === tabName ? "var(--primary)" : "transparent";
      });
      container.querySelectorAll(".detail-content").forEach(c => {
        c.style.display = c.id === "tab-" + tabName ? "block" : "none";
      });
    });
  });

  // 7. 責任者割当ボタン
  container.querySelector("[data-testid='assign-button']").addEventListener("click", async () => {
    const ownerId = container.querySelector("[data-testid='owner-select']").value;
    if (!ownerId) {
      alert("責任者を選択してください");
      return;
    }
    if (selectedErrorId !== null) {
      const error = currentErrors.find((err, idx) => (err.id || idx) == selectedErrorId);
      if (error) {
        error.assignedOwnerId = ownerId;
        await window.aivicApi.update(errorLogIndex, error.id || selectedErrorId, { assignedOwnerId: ownerId });
        alert("責任者を割当しました");
      }
    }
  });

  // 8. 通知送信ボタン
  container.querySelector("[data-testid='send-notify-button']").addEventListener("click", async () => {
    const channels = [];
    if (container.querySelector("[data-testid='notify-email']").checked) channels.push("email");
    if (container.querySelector("[data-testid='notify-slack']").checked) channels.push("slack");
    if (container.querySelector("[data-testid='notify-system']").checked) channels.push("system");

    const message = container.querySelector("[data-testid='notify-message']").value;
    if (!message) {
      alert("通知内容を入力してください");
      return;
    }
    if (channels.length === 0) {
      alert("通知チャネルを選択してください");
      return;
    }

    // 通知送信（シミュレーション）
    await window.aivicApi.save(1, {
      notificationType: "error",
      channels: channels.join(","),
      message: message,
      sentAt: new Date().toISOString()
    });
    alert("通知を送信しました");
    container.querySelector("[data-testid='notify-message']").value = "";
  });

  // 9. ファイルアップロード処理
  const uploadZone = container.querySelector("#upload-zone");
  const fileInput = container.querySelector("#file-input");
  const fileName = container.querySelector("#file-name");

  uploadZone.addEventListener("dragover", (e) => {
    e.preventDefault();
    uploadZone.style.background = "rgba(255,255,255,0.1)";
  });

  uploadZone.addEventListener("dragleave", () => {
    uploadZone.style.background = "rgba(0,0,0,0.15)";
  });

  uploadZone.addEventListener("drop", (e) => {
    e.preventDefault();
    uploadZone.style.background = "rgba(0,0,0,0.15)";
    const files = e.dataTransfer.files;
    if (files.length > 0) {
      fileInput.files = files;
      fileName.textContent = "📄 " + files[0].name;
    }
  });

  fileInput.addEventListener("change", (e) => {
    if (e.target.files.length > 0) {
      fileName.textContent = "📄 " + e.target.files[0].name;
    }
  });
}
